/**
 * J18: the built artifact is self-contained.
 *
 * Every import in `dist/*.js` must be a Node builtin, the workspace contracts package, `zod` or a
 * sibling module — nothing else. `dist` is generated by `tsconfig.build.json`; when it is absent the
 * check is skipped rather than silently passing.
 */
import assert from 'node:assert/strict'
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { test } from 'node:test'

const root = dirname(dirname(fileURLToPath(import.meta.url)))
const dist = join(root, 'dist')
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as {
  exports: Record<string, unknown>
  files: string[]
  dependencies: Record<string, string>
  devDependencies: Record<string, string>
}

test('the published entry points at dist and ships only dist plus README', () => {
  assert.deepEqual(pkg.exports['.'], { types: './dist/index.d.ts', import: './dist/index.js' })
  assert.deepEqual([...pkg.files].sort(), ['README.md', 'dist'])
  assert.deepEqual(Object.keys(pkg.dependencies).sort(), ['@personal-agent/contracts', 'zod'])
  assert.equal('@personal-agent/application' in { ...pkg.dependencies, ...pkg.devDependencies }, false)
})

test('every dist import is a builtin, contracts, zod or a sibling module', (t) => {
  if (!existsSync(join(dist, 'index.js'))) {
    t.skip('dist is not built; run tsc -p tsconfig.build.json first')
    return
  }
  const files = readdirSync(dist).filter((name) => name.endsWith('.js'))
  assert.ok(files.length > 0)
  const specifiers = new Set<string>()
  for (const name of files) {
    const text = readFileSync(join(dist, name), 'utf8')
    for (const match of text.matchAll(/from\s+'([^']+)'|import\(\s*'([^']+)'\s*\)/g)) specifiers.add(match[1] ?? match[2] ?? '')
  }
  const allowed = (specifier: string): boolean =>
    specifier.startsWith('node:') || specifier.startsWith('./') || specifier === 'zod' ||
    specifier === '@personal-agent/contracts' || specifier === '@personal-agent/contracts/canonical'
  const foreign = [...specifiers].filter((specifier) => !allowed(specifier))
  assert.deepEqual(foreign, [])
})
